"""Markdown report. Always a draft: the sign-off block is left for a human auditor.

Every value that comes from the auditee's documents or from the model goes through cell(), which
escapes HTML and Markdown, so the report cannot carry live images, links, raw HTML or scripts
(SAAF Guard rule 9).
"""
from __future__ import annotations

import html
import re
from datetime import date

from .findings import is_readiness_gap
from .guard import sha256_text
from .pipeline import AuditResult

BANNER = (
    "> **AI-ASSISTED DRAFT - NOT AN AUDIT OPINION.** Generated by the EU AI Act + DNB Auditor. "
    "Every status below must be reviewed by a qualified auditor before use. Regulatory references "
    "are paraphrased summaries; check their verification status in regulatory/criteria.json. Not legal advice."
)

STATUS_ICON = {
    "met": "met", "partially_met": "PARTIAL", "not_met": "NOT MET",
    "not_evidenced": "NO EVIDENCE", "not_applicable": "n/a", "inconclusive": "INCONCLUSIVE",
}

_MD_SPECIAL = re.compile(r"([\\`*_{}\[\]()#+!|~>])")


def cell(text: object) -> str:
    """Escape untrusted text for Markdown tables and paragraphs: no HTML, links, images or line breaks."""
    s = html.escape(str(text), quote=True)          # <img>, <script>, entities
    s = _MD_SPECIAL.sub(r"\\\1", s)                  # ![x](...), [x](...), emphasis, code, tables
    s = re.sub(r"(?i)\b(javascript|data|vbscript)\s*:", r"\1&#58;", s)   # neutralise URL schemes
    return re.sub(r"\s+", " ", s).strip()


def render(r: AuditResult) -> str:
    s, c = r.system, r.classification
    readiness = sum(1 for f in r.findings if f["observation"].startswith("Readiness gap"))
    lines = [
        f"# AI System Audit - {cell(s['name'])}",
        "",
        BANNER,
        "",
        f"**Overall result: {r.verdict}**  ",
        f"Findings: {len(r.findings)} ({readiness} readiness gaps for obligations not yet in force) · "
        f"Criteria assessed: {len(r.criteria)} · Generated: {date.today().isoformat()}",
        "",
        "## 1. Scope",
        "",
        "| Field | Value |",
        "|---|---|",
        f"| System | {cell(s['id'])} - {cell(s['name'])} |",
        f"| Organisation | {cell(s['organisation'])} ({cell(s['organisation_type'])}) |",
        f"| Declared role | {cell(s['role'])} |",
        f"| Intended purpose | {cell(s['intended_purpose'])} |",
        f"| Third-party provider | {cell(s.get('third_party_provider') or '-')} |",
        f"| Scope facts used to select laws | {cell(', '.join(r.scope_facts))} |",
        f"| system.json SHA-256 | `{r.system_sha256}` |",
        "",
        "> The scope facts above come from system.json and decide which laws are tested. "
        "The auditor, not the auditee, must confirm them.",
        "",
        "Evidence examined (SHA-256):",
        "",
    ]
    lines += [f"- {cell(name)} - `{sha256_text(text)[:16]}...`" for name, text in r.documents.items()]
    if r.skipped:
        lines += ["", "**Files refused at load time (not examined):**", ""] + [f"- {cell(x)}" for x in r.skipped]
    lines += [
        "",
        "## 2. EU AI Act classification",
        "",
        f"- **Tier(s):** {cell(', '.join(c.tiers)) or 'none returned'}",
        f"- **Annex III area:** {cell(c.annex_iii_area) or '-'}",
        f"- **Art. 6(3) carve-out applies:** {'yes' if c.art_6_3_carve_out_applies else 'no'}",
        f"- **Role:** {cell(c.role)}",
        f"- **FRIA required (Art. 27):** {'yes' if c.fria_required else 'no'}",
        f"- **Rationale:** {cell(c.rationale)}",
        "",
    ]
    if c.triggers:
        lines += ["| Article | Trigger (quoted from evidence) |", "|---|---|"]
        lines += [f"| {cell(t.article)} | \"{cell(t.trigger_quote)}\" |" for t in c.triggers]
        lines.append("")
    flags = list(c.uncertainty_flags) + r.classification_notes
    if flags:
        lines += ["**Uncertainty / verifier notes:**", ""] + [f"- {cell(f)}" for f in flags] + [""]

    if r.notes:
        lines += ["## 3. Financial-sector considerations", ""]
        for n in r.notes:
            lines += [f"- **{cell(n['id'])}** ({cell(n['reference'])}): {cell(n['note'])} *\\[{cell(n['verification_status'])}\\]*"]
        lines.append("")

    lines += [
        "## 4. Criteria results",
        "",
        "| ID | Reference | Criterion | Status | Evidence | Gap |",
        "|---|---|---|---|---|---|",
    ]
    today = date.today()
    for v in r.criteria:
        ev = "<br>".join(f"\"{cell(q)}\"" for q in v.evidence_quotes[:2]) or "-"
        status = f"**{STATUS_ICON[v.status]}**"
        if is_readiness_gap(v, today):
            status += f"<br>*applies from {cell(v.applies_from)}*"
        lines.append(f"| {cell(v.criterion_id)} | {cell(v.reference)} | {cell(v.title)} | {status} | {ev} | {cell(v.gap) or '-'} |")
    lines.append("")

    favourable = [v for v in r.criteria if v.status in ("met", "not_applicable")]
    lines += ["### Favourable conclusions to confirm", "",
              "The verifier only checks that a quote exists, not that it proves the criterion. "
              "Confirm each one before accepting it.", ""]
    lines += [f"- ☐ {cell(v.criterion_id)} ({STATUS_ICON[v.status]}): "
              + ("; ".join(f"\"{cell(q)}\"" for q in v.evidence_quotes) or cell(v.gap) or "-") for v in favourable] \
        or ["- None."]
    lines.append("")

    lines += ["## 5. Draft findings", ""]
    if not r.findings:
        lines += ["No findings drafted.", ""]
    for f in r.findings:
        lines += [
            f"### {cell(f['id'])} - {cell(f['title'])} ({cell(f['risk_rating'])})",
            "",
            f"- **Control objective:** {cell(f['control_objective'])}",
            f"- **Observation:** {cell(f['observation'])}",
            f"- **Recommendation:** {cell(f['recommendation'])}",
            f"- **Owner:** {cell(f['owner'])} · **Status:** {cell(f['status'])} · AI-assisted",
            "",
        ]

    notes = [(v.criterion_id, n) for v in r.criteria for n in v.verifier_notes]
    lines += ["## 6. Verification log", "", "Deterministic checks applied to the model output (quote grounding, missing criteria, unsupported statuses):", ""]
    lines += [f"- {cell(cid)}: {cell(n)}" for cid, n in notes] or ["- No corrections were needed."]
    lines += ["", "Model calls:", ""]
    lines += [f"- {cell(k['step'])}: {cell(k['model'])} · request `{cell(k['request_id']) or '-'}` · stop `{cell(k['stop_reason'])}` · "
              f"tokens in/out {int(k['input_tokens'])}/{int(k['output_tokens'])}" for k in r.calls]
    if r.trail_head:
        lines += ["", f"Audit trail head (HMAC of the closing record): `{r.trail_head}`. "
                  "Check with `python -m auditor verify-trail <trail.jsonl> --head <value>`; a shortened or altered trail will not match."]

    lines += [
        "",
        "## 7. Auditor sign-off",
        "",
        "| | |",
        "|---|---|",
        "| Reviewed by | |",
        "| Date | |",
        "| Decision | ☐ Accept findings as drafted ☐ Accept with changes ☐ Reject |",
        "| Scope facts in system.json confirmed by the auditor | ☐ |",
        "| Favourable conclusions confirmed | ☐ |",
        "| Regulatory references verified | ☐ |",
        "",
    ]
    return "\n".join(lines)
